<template><div class="form-page"><el-form label-width="170px" label-position="left"><MetadataEditor :model="localForm" title="基础配置" /><el-card shadow="never"><template #header>CronJob 配置</template><div class="grid-four"><el-form-item label="定时表达式"><el-input v-model="localForm.schedule" placeholder="*/5 * * * *" /></el-form-item><el-form-item label="启动超时秒数"><el-input-number v-model="localForm.startingDeadlineSeconds" :min="0" /></el-form-item><el-form-item label="并发策略"><el-select v-model="localForm.concurrencyPolicy"><el-option label="Allow" value="Allow" /><el-option label="Forbid" value="Forbid" /><el-option label="Replace" value="Replace" /></el-select></el-form-item><el-form-item label="successful history"><el-input-number v-model="localForm.successfulJobHistoryLimit" :min="0" /></el-form-item><el-form-item label="failed history"><el-input-number v-model="localForm.failedJobHistoryLimit" :min="0" /></el-form-item><el-form-item label="完成数"><el-input-number v-model="localForm.completions" :min="1" /></el-form-item><el-form-item label="并行数"><el-input-number v-model="localForm.parallelism" :min="1" /></el-form-item><el-form-item label="重试上限"><el-input-number v-model="localForm.backoffLimit" :min="0" /></el-form-item></div></el-card><PodTemplateEditor :model="localForm.podTemplate" title="Job Pod 模板" /></el-form></div></template>
